<?php
namespace App\Models;
use App\Enums\AssignmentStatus;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['assignment_code','customer_id','customer_requirement_id','worker_id','service_id','duty_type_id','assignment_start_date','assignment_end_date','working_hours_text','monthly_salary','agency_service_charge','work_location','status','confirmed_at','started_at','completed_at','cancelled_at','assigned_by','notes'])]
class Assignment extends Model {protected static function booted():void{static::updating(fn(self $m)=>$m->isDirty('assignment_code')?$m->assignment_code=$m->getOriginal('assignment_code'):null);}public function customer():BelongsTo{return $this->belongsTo(Customer::class);}public function requirement():BelongsTo{return $this->belongsTo(CustomerRequirement::class,'customer_requirement_id');}public function worker():BelongsTo{return $this->belongsTo(Worker::class);}public function service():BelongsTo{return $this->belongsTo(Service::class);}public function dutyType():BelongsTo{return $this->belongsTo(DutyType::class);}public function statusHistory():HasMany{return $this->hasMany(AssignmentStatusHistory::class);}public function replacementRequests():HasMany{return $this->hasMany(ReplacementRequest::class);}public function agreements():HasMany{return $this->hasMany(Agreement::class);}public function invoices():HasMany{return $this->hasMany(Invoice::class);}protected function casts():array{return ['assignment_start_date'=>'date','assignment_end_date'=>'date','confirmed_at'=>'datetime','started_at'=>'datetime','completed_at'=>'datetime','cancelled_at'=>'datetime','monthly_salary'=>'decimal:2','agency_service_charge'=>'decimal:2','status'=>AssignmentStatus::class];}}
